import json,html
from pathlib import Path
from cbim_sdk import CBIMProject
from .models import ImportPlan,ConversionReport

def _safe_json(value):return json.dumps(value,ensure_ascii=False).replace('</','<\\/')

def build_studio_html(project:CBIMProject,plan:ImportPlan,report:ConversionReport)->str:
    p=_safe_json(project.model_dump(mode='json',exclude_computed_fields=True));pl=_safe_json(plan.model_dump(mode='json'));rp=_safe_json(report.model_dump(mode='json'))
    return '''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CompatibilizaBIM Studio</title><style>
*{box-sizing:border-box}body{margin:0;font-family:Inter,ui-sans-serif,system-ui;background:#f5f7fa;color:#13202b}header{height:64px;background:#111b24;color:white;display:flex;align-items:center;padding:0 24px;justify-content:space-between}.brand{font-weight:800;font-size:20px}.header-status{display:flex;align-items:center;gap:16px}.save-state{color:#d7e3ec;font-size:13px}.shell{display:grid;grid-template-columns:230px 1fr;height:calc(100vh - 64px)}nav{background:#fff;border-right:1px solid #dde3ea;padding:18px 12px}nav button{display:block;width:100%;text-align:left;border:0;background:transparent;padding:11px 12px;border-radius:8px;margin:3px 0;font-weight:650;color:#33495c;cursor:pointer}nav button.active{background:#e1edf6;color:#102a43}main{overflow:auto;padding:26px}.page{display:none}.page.active{display:block}.title{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:20px}.grid{display:grid;grid-template-columns:repeat(4,minmax(140px,1fr));gap:12px}.card{background:white;border:1px solid #cbd5df;border-radius:12px;padding:16px}.metric{font-size:28px;font-weight:800}.muted{color:#516475}.source,.element,.rule{background:#fff;border:1px solid #cbd5df;border-radius:10px;padding:12px;margin:8px 0}.badge{display:inline-block;padding:4px 8px;border-radius:999px;background:#e7edf3;font-size:12px;font-weight:650}.ok{background:#ccebd9;color:#164e32}.warn{background:#ffedb3;color:#624000}.bad{background:#ffd4d4;color:#731c1c}button.action{border:1px solid #9eafbd;background:#fff;color:#13202b;padding:8px 11px;border-radius:8px;cursor:pointer}button.action:disabled{opacity:.55;cursor:not-allowed}button.primary{background:#163a5f;color:#fff;border-color:#163a5f}input,select{width:100%;padding:9px;border:1px solid #98aaba;border-radius:7px;background:#fff;color:#13202b}label.field{display:block;font-weight:650}label.field span{display:block;margin-bottom:6px}.review-layout{display:grid;grid-template-columns:1fr 380px;gap:14px;height:calc(100vh - 150px)}#canvasWrap{background:#0c1218;border-radius:12px;overflow:hidden;min-height:420px}canvas{width:100%;height:100%}.side{overflow:auto}.toolbar{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:10px}.toolbar .search{grid-column:1/-1}table{width:100%;border-collapse:collapse;background:#fff}td,th{padding:10px;border-bottom:1px solid #dce4eb;text-align:left}:focus-visible{outline:3px solid #2f76b3;outline-offset:2px}.notice{border-left:4px solid #2f6b9a}.recovery-card{border-left:4px solid #c47700}@media(max-width:900px){.shell{grid-template-columns:1fr}nav{display:flex;overflow:auto;border-right:0;border-bottom:1px solid #ddd}.grid{grid-template-columns:1fr 1fr}.review-layout{grid-template-columns:1fr;height:auto}#canvasWrap{height:450px}.title{align-items:flex-start;flex-direction:column}}
</style></head><body><header><div class=brand>CompatibilizaBIM Studio</div><div class=header-status><span id=saveState class=save-state role=status aria-live=polite>Projeto carregado</span><div id=projectName></div></div></header><div class=shell><nav id=nav aria-label="Etapas do projeto"><button data-page=import class=active>1. Fontes</button><button data-page=config>2. Configuração</button><button data-page=review>3. Revisão</button><button data-page=profiles>4. Perfis CAD</button><button data-page=report>5. Exportação</button></nav><main>
<section id=import class="page active"><div class=title><div><h1>Fontes do projeto</h1><div class=muted>Confira os arquivos que originaram esta conversão</div></div><span id=ready></span></div><div class="card notice"><b>Conversão concluída</b><p class=muted>Esta área revisa o resultado já processado. Para converter outro DWG ou IFC, volte à tela “Estudos e conflitos” do aplicativo principal.</p></div><div id=sources></div></section>
<section id=config class=page><div class=title><div><h1>Configuração</h1><div class=muted>Parâmetros usados pelo reconhecimento e reconstrução 3D</div></div><button class="action primary" onclick="downloadConfig()">Exportar configuração</button></div><div class=grid id=configCards></div><div class=title style="margin-top:24px"><h2>Pavimentos</h2><button class=action onclick=addStorey()>Adicionar pavimento</button></div><table id=storeys></table></section>
<section id=review class=page><div class=title><div><h1>Revisar reconhecimento</h1><div class=muted>Confirme, ajuste ou rejeite elementos antes da exportação</div></div><div><button class=action onclick=undo()>Desfazer</button> <button class=action onclick=redo()>Refazer</button> <button class="action primary" onclick=saveWorkspaceProject()>Salvar alterações</button></div></div><div class=review-layout><div id=canvasWrap><canvas id=c role=img aria-label="Visualização bidimensional dos elementos reconhecidos"></canvas></div><div class=side><div class=toolbar><label class="field search"><span>Buscar elemento</span><input id=elementSearch type=search placeholder="Nome, tipo ou código" oninput=renderReview()></label><label class=field><span>Status</span><select id=stateFilter onchange=renderReview()><option value="">Todos</option><option value=auto>Pendente</option><option value=confirmed>Confirmado</option><option value=edited>Ajustado</option><option value=rejected>Rejeitado</option></select></label><label class=field><span>Tipo</span><select id=typeFilter onchange=renderReview()><option value="">Todos os tipos</option></select></label></div><div id=reviewStats></div><div id=elements></div></div></div></section>
<section id=profiles class=page><div class=title><div><h1>Aprendizado de perfil CAD</h1><div class=muted>Correções humanas podem virar regras reutilizáveis; reconhecimentos automáticos nunca ensinam sozinhos</div></div><button class="action primary" onclick=downloadLearnedProfile()>Exportar perfil aprendido</button></div><div class=card><b>Política de aprendizado</b><p>Somente elementos <code>confirmed</code> ou <code>edited</code> são elegíveis. Uma regra exige múltiplas observações consistentes antes de ser promovida.</p></div><div id=profileCandidates></div></section>
<section id=report class=page><div class=title><div><h1>Validar e exportar</h1><div class=muted>O arquivo final só é liberado quando todas as verificações obrigatórias forem atendidas</div></div><div><button class=action onclick=downloadReport()>Baixar relatório técnico</button> <button id=exportButton class="action primary" onclick=downloadCBIM()>Exportar CBIM revisado</button></div></div><div class=grid id=metrics></div><h2>Elementos</h2><table id=counts></table><h2>Verificações obrigatórias</h2><div id=blockers></div></section>
</main></div><script>
let project='''+p+''', plan='''+pl+''', report='''+rp+''', selected=null, undoStack=[], redoStack=[];
const deep=x=>JSON.parse(JSON.stringify(x)),esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char])),stateLabels={auto:'Pendente',confirmed:'Confirmado',edited:'Ajustado',rejected:'Rejeitado'},disciplineLabels={unknown:'Não definida',architecture:'Arquitetura',structure:'Estrutura',hydraulic:'Hidráulica',fire:'Incêndio'};let dirty=false;
function setDirty(value=true){dirty=value;document.getElementById('saveState').textContent=value?'Alterações não salvas':'Todas as alterações foram salvas'}document.getElementById('projectName').textContent=project.name;
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{document.querySelectorAll('nav button,.page').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.getElementById(b.dataset.page).classList.add('active');if(b.dataset.page==='review')setTimeout(draw,0);if(b.dataset.page==='profiles')renderProfiles();if(b.dataset.page==='report')renderReport()});
function badge(text,cls=''){return `<span class="badge ${cls}">${esc(text)}</span>`}
function recomputePlan(){plan.ready=plan.sources.some(s=>s.enabled)&&plan.sources.filter(s=>s.enabled).every(s=>s.discipline!=='unknown');plan.warnings=plan.ready?[]:['Confirme a disciplina de todas as fontes habilitadas']}function setDisc(i,v){plan.sources[i].discipline=v;plan.sources[i].warnings=v==='unknown'?['Disciplina requer confirmação']:[];recomputePlan();setDirty();renderImport()}function renderImport(){recomputePlan();document.getElementById('ready').innerHTML=badge(plan.ready?'Fontes validadas':'Requer revisão',plan.ready?'ok':'warn');document.getElementById('sources').innerHTML=plan.sources.map((s,i)=>`<div class=source><b>${esc(s.name)}</b> ${badge(s.source_format.toUpperCase())}<label class=field><span>Disciplina</span><select aria-label="Disciplina de ${esc(s.name)}" onchange="setDisc(${i},this.value)">${Object.entries(disciplineLabels).map(([value,label])=>`<option value="${esc(value)}" ${s.discipline===value?'selected':''}>${esc(label)}</option>`).join('')}</select></label><div class=muted>${esc(s.path)}</div>${s.warnings.map(w=>`<div>${badge(w==='Discipline requires confirmation'?'Disciplina requer confirmação':w,'warn')}</div>`).join('')}</div>`).join('')+plan.warnings.map(w=>`<div class=source>${badge(w,'warn')}</div>`).join('')}
function renderConfig(){let c=plan.config;document.getElementById('configCards').innerHTML=`<div class=card><label class=field><span>Nome do projeto</span><input value="${esc(c.project_name)}" onchange="plan.config.project_name=this.value;project.name=this.value;document.getElementById('projectName').textContent=this.value;setDirty()"></label></div><div class=card><label class=field><span>Unidade</span><select onchange="plan.config.units=this.value;setDirty()"><option ${c.units==='m'?'selected':''}>m</option><option ${c.units==='mm'?'selected':''}>mm</option><option ${c.units==='cm'?'selected':''}>cm</option></select></label></div><div class=card><label class=field><span>Sistema de coordenadas</span><input value="${esc(c.coordinate_reference)}" onchange="plan.config.coordinate_reference=this.value;setDirty()"></label></div><div class=card><label class=field><span>Fabricante preferencial</span><input value="${esc(c.preferred_manufacturer||'')}" placeholder="Seleção automática" onchange="plan.config.preferred_manufacturer=this.value||null;setDirty()"></label></div>`;document.getElementById('storeys').innerHTML='<tr><th>Pavimento</th><th>Cota</th><th>Altura</th><th>Ação</th></tr>'+c.storeys.map((s,i)=>`<tr><td><input aria-label="Nome do pavimento ${i+1}" value="${esc(s.name)}" onchange="plan.config.storeys[${i}].name=this.value;setDirty()"></td><td><input aria-label="Cota do pavimento ${i+1}" type=number step=.01 value="${s.elevation}" onchange="plan.config.storeys[${i}].elevation=+this.value;setDirty()"></td><td><input aria-label="Altura do pavimento ${i+1}" type=number step=.01 min=.01 value="${s.height}" onchange="plan.config.storeys[${i}].height=+this.value;setDirty()"></td><td><button class=action onclick="plan.config.storeys.splice(${i},1);setDirty();renderConfig()">Remover</button></td></tr>`).join('')}function addStorey(){let c=plan.config.storeys,last=c[c.length-1],e=last?last.elevation+last.height:0;c.push({name:'Novo pavimento',elevation:e,height:2.8});setDirty();renderConfig()}
function color(e){if(e.review_state==='rejected')return '#dc4a4a';if(e.review_state==='confirmed')return '#32b67a';if(e.review_state==='edited')return '#8a66cc';if(e.confidence>=.85)return '#42a5d9';if(e.confidence>=.6)return '#e0ad3b';return '#e66555'}
function pts(){let a=[];project.elements.forEach(e=>{if(e.start)a.push(e.start,e.end);if(e.center)a.push(e.center);if(e.position)a.push(e.position);if(e.path)a.push(...e.path);if(e.boundary)a.push(...e.boundary)});return a}
function draw(){let c=document.getElementById('c'),r=c.getBoundingClientRect();if(!r.width||!r.height)return;c.width=r.width*devicePixelRatio;c.height=r.height*devicePixelRatio;let all=pts();if(!all.length)return;let xs=all.map(q=>q.x),ys=all.map(q=>q.y),minx=Math.min(...xs),maxx=Math.max(...xs),miny=Math.min(...ys),maxy=Math.max(...ys),s=Math.min(c.width/(maxx-minx+1),c.height/(maxy-miny+1))*.82,tx=c.width*.09-minx*s,ty=c.height*.91+miny*s,ctx=c.getContext('2d'),P=q=>[q.x*s+tx,ty-q.y*s];ctx.clearRect(0,0,c.width,c.height);ctx.lineWidth=2.5*devicePixelRatio;project.elements.forEach(e=>{ctx.strokeStyle=color(e);ctx.fillStyle=color(e);ctx.lineWidth=(e.id===selected?5:2.5)*devicePixelRatio;if(e.start){let a=P(e.start),b=P(e.end);ctx.beginPath();ctx.moveTo(...a);ctx.lineTo(...b);ctx.stroke()}if(e.path){ctx.beginPath();e.path.forEach((q,i)=>{let v=P(q);i?ctx.lineTo(...v):ctx.moveTo(...v)});ctx.stroke()}if(e.boundary){ctx.beginPath();e.boundary.forEach((q,i)=>{let v=P(q);i?ctx.lineTo(...v):ctx.moveTo(...v)});ctx.closePath();ctx.stroke()}if(e.position||e.center){let v=P(e.position||e.center);ctx.beginPath();ctx.arc(v[0],v[1],5*devicePixelRatio,0,Math.PI*2);ctx.fill()}})}
function snap(){undoStack.push(deep(project));redoStack=[]}function setState(id,state){snap();let e=project.elements.find(x=>x.id===id);e.review_state=state;selected=id;setDirty();renderReview()}function undo(){if(!undoStack.length)return;redoStack.push(deep(project));project=undoStack.pop();setDirty();renderReview()}function redo(){if(!redoStack.length)return;undoStack.push(deep(project));project=redoStack.pop();setDirty();renderReview()}
function selectElement(node){selected=node.dataset.elementId;draw()}function renderReview(){let sf=document.getElementById('stateFilter').value,tf=document.getElementById('typeFilter').value,q=document.getElementById('elementSearch').value.trim().toLowerCase();let els=project.elements.filter(e=>(!sf||e.review_state===sf)&&(!tf||e.type===tf)&&(!q||[e.id,e.type,e.name].some(v=>String(v||'').toLowerCase().includes(q))));let st={};project.elements.forEach(e=>st[e.review_state]=(st[e.review_state]||0)+1);document.getElementById('reviewStats').innerHTML='<div class=card>'+Object.entries(st).map(([k,v])=>`${badge(stateLabels[k]||k)} <b>${v}</b>`).join(' &nbsp; ')+'</div>';document.getElementById('elements').innerHTML=els.map(e=>`<div class=element tabindex=0 data-element-id="${esc(e.id)}" onclick="selectElement(this)"><b>${esc(e.type)}</b> ${esc(e.name||'')}<div class=muted>${esc(e.id)} · ${Math.round(e.confidence*100)}% · ${esc(stateLabels[e.review_state]||e.review_state)}</div><div><button class=action onclick="event.stopPropagation();setState(this.closest('.element').dataset.elementId,'confirmed')">Confirmar</button><button class=action onclick="event.stopPropagation();setState(this.closest('.element').dataset.elementId,'edited')">Marcar como ajustado</button><button class=action onclick="event.stopPropagation();setState(this.closest('.element').dataset.elementId,'rejected')">Rejeitar</button></div></div>`).join('')||'<div class=card>Nenhum elemento corresponde aos filtros.</div>';draw()}
function learnedProfile(){let grouped={};project.elements.filter(e=>['confirmed','edited'].includes(e.review_state)).forEach(e=>(e.source_refs||[]).forEach(r=>{if(!r.layer)return;let layer=r.layer.toUpperCase();grouped[layer]=grouped[layer]||{};grouped[layer][e.type]=(grouped[layer][e.type]||0)+1}));let rules=[];Object.entries(grouped).forEach(([layer,types])=>{let pairs=Object.entries(types).sort((a,b)=>b[1]-a[1]),total=pairs.reduce((a,x)=>a+x[1],0),[target,n]=pairs[0];if(total>=2&&n/total>=.8)rules.push({id:'learned-layer-'+layer.toLowerCase().replace(/[^a-z0-9]+/g,'-'),target,layer,block:null,match:'exact',system:null,defaults:{},priority:100})});return{name:'Perfil aprendido - '+project.name,version:'1.0',organization:plan.config.organization||null,rules}}function renderProfiles(){let p=learnedProfile(),all={};project.elements.filter(e=>['confirmed','edited'].includes(e.review_state)).forEach(e=>(e.source_refs||[]).forEach(r=>{if(r.layer)all[r.layer.toUpperCase()]=(all[r.layer.toUpperCase()]||0)+1}));document.getElementById('profileCandidates').innerHTML=Object.entries(all).sort().map(([k,n])=>`<div class=rule><b>${esc(k)}</b> ${badge(n+' observações',n>=2?'ok':'warn')}<div class=muted>${p.rules.some(r=>r.layer===k)?'Regra promovida':'Ainda não promovida'}</div></div>`).join('')||'<div class=card>Nenhuma regra elegível ainda.</div>'}function downloadLearnedProfile(){save(learnedProfile(),'learned-cad-profile.json')}
function recomputeReport(){recomputePlan();let states={};project.elements.forEach(e=>states[e.review_state]=(states[e.review_state]||0)+1);report.total_elements=project.elements.length;report.review_states=states;report.pending_review=(states.auto||0)+(states.rejected||0);report.confirmed_or_edited=(states.confirmed||0)+(states.edited||0);report.completion_rate=project.elements.length?report.confirmed_or_edited/project.elements.length:0;report.blockers=[];if(!project.elements.length)report.blockers.push('A conversão não contém elementos exportáveis');if(!plan.sources.some(s=>s.enabled))report.blockers.push('Nenhuma fonte de projeto está habilitada');if(plan.sources.filter(s=>s.enabled).some(s=>s.discipline==='unknown'))report.blockers.push('Confirme a disciplina de todas as fontes habilitadas');if(!String(plan.config.project_name||'').trim())report.blockers.push('Informe o nome do projeto');if(!plan.config.storeys.length)report.blockers.push('Cadastre pelo menos um pavimento');if(states.auto)report.blockers.push(`${states.auto} elemento(s) automático(s) ainda requer(em) revisão`);if(states.rejected)report.blockers.push(`${states.rejected} elemento(s) rejeitado(s) permanecem no projeto`);report.ready_to_export=!report.blockers.length}
function renderReport(){recomputeReport();document.getElementById('metrics').innerHTML=`<div class=card><div class=metric>${report.total_elements}</div><div class=muted>Elementos</div></div><div class=card><div class=metric>${Math.round(report.mean_confidence*100)}%</div><div class=muted>Confiança</div></div><div class=card><div class=metric>${Math.round(report.completion_rate*100)}%</div><div class=muted>Revisado</div></div><div class=card><div class=metric>${report.pending_review}</div><div class=muted>Pendências</div></div>`;document.getElementById('counts').innerHTML='<tr><th>Tipo</th><th>Quantidade</th></tr>'+Object.entries(report.element_counts).map(([k,v])=>`<tr><td>${esc(k)}</td><td>${v}</td></tr>`).join('');document.getElementById('blockers').innerHTML=report.blockers.length?report.blockers.map(b=>`<div class=source>${badge(b,'bad')}</div>`).join(''):`<div class=source>${badge('Todas as verificações foram atendidas','ok')}</div>`;let button=document.getElementById('exportButton');button.disabled=!report.ready_to_export;button.title=report.ready_to_export?'Exportar arquivo revisado':'Resolva as verificações obrigatórias antes de exportar'}
async function saveWorkspaceProject(){let state=document.getElementById('saveState');state.textContent='Salvando...';try{let r=await fetch('/api/workspace',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({project,plan})});if(!r.ok){let e=await r.json().catch(()=>({error:'Falha ao salvar'}));throw new Error(e.error||'Falha ao salvar')}let st=await r.json();setDirty(false);state.textContent='Salvo na revisão '+st.revision}catch(e){state.textContent='Não foi possível salvar';alert('Falha ao salvar: '+e.message)}}function save(obj,name){let b=new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}function downloadCBIM(){recomputeReport();if(!report.ready_to_export){renderReport();alert('A exportação está bloqueada. Resolva as verificações obrigatórias.');return}save(project,'reviewed.cbim.json')}function downloadConfig(){save(plan.config,'project-config.json')}function downloadReport(){recomputeReport();save(report,'conversion-report.json')}
let types=[...new Set(project.elements.map(e=>e.type))].sort();document.getElementById('typeFilter').innerHTML+=types.map(t=>`<option value="${esc(t)}">${esc(t)}</option>`).join('');window.onbeforeunload=event=>{if(dirty){event.preventDefault();event.returnValue=''}};window.onresize=draw;renderImport();renderConfig();renderReview();renderProfiles();renderReport();
</script></body></html>'''

def write_studio(project:CBIMProject,plan:ImportPlan,report:ConversionReport,path:str|Path)->Path:
    p=Path(path);p.write_text(build_studio_html(project,plan,report),encoding='utf-8');return p
